IF (SELECT COUNT(*) FROM @AppearanceInput) <> 9434
    THROW 52002, 'Expected 9,434 sourced appearances.', 1;

IF EXISTS (
    SELECT 1
    FROM @AppearanceInput AS input
    LEFT JOIN dbo.person AS person
        ON person.name = input.player_name
    LEFT JOIN dbo.player AS player
        ON player.person_id = person.person_id
    WHERE player.person_id IS NULL
)
    THROW 52003, 'Every lineup entry must resolve to a player profile.', 1;

IF EXISTS (SELECT 1 FROM dbo.appearance)
    THROW 52004, 'Lineups are already loaded.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO dbo.appearance (match_id, player_id, is_starter)
    SELECT match_map.match_id, player.person_id, input.is_starter
    FROM @AppearanceInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.player_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
